import { expect, SkyrampClient, getBaseUrl, getResponseValue } from '@skyramp/skyramp';
import type { APIRequestContext, Page, PlaywrightWorkerArgs } from '@playwright/test';

// URL for test requests
export const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

// Linkwarden authenticates every /api/v1 route through next-auth; the session token is
// supplied to the run as SKYRAMP_TEST_TOKEN and is accepted as a bearer credential.
export const authHeaders = { Authorization: `Bearer ${process.env.SKYRAMP_TEST_TOKEN ?? ""}` };

// The secondary account these tests use as the other identity. It is registered on the first
// run and resolved by username on every later run, so repeated runs do not pile up accounts.
export const MEMBER_USERNAME = "testbot-member";
export const MEMBER_PASSWORD = "TestbotMember123!";
export const MEMBER_NAME = "Testbot Member";

export async function createUser(
    client: SkyrampClient,
    username: string = MEMBER_USERNAME,
    password: string = MEMBER_PASSWORD,
    name: string = MEMBER_NAME,
) {
    // No status assertion here: registration answers 201 the first time an account is created
    // and 400 on every later run, and both are a usable starting point for these tests.
    return client.sendRequest({
        url: URL_localhost,
        path: "/api/v1/users",
        method: "POST",
        body: JSON.stringify({ username, password, name }),
    });
}

export async function getUsersList(client: SkyrampClient, expectedStatus = 200) {
    const response = await client.sendRequest({
        url: URL_localhost,
        path: "/api/v1/users",
        method: "GET",
        headers: authHeaders,
    });
    expect(response.statusCode, 'status code').toBe(expectedStatus);
    return response;
}

