// Signs in with the credentials provider and returns a request context bound to that account.
export async function signInAs(
    playwright: PlaywrightWorkerArgs['playwright'],
    username: string = MEMBER_USERNAME,
    password: string = MEMBER_PASSWORD,
): Promise<APIRequestContext> {
    const signInContext = await playwright.request.newContext({ baseURL: URL_localhost });
    const csrf = await (await signInContext.get("/api/v1/auth/csrf")).json();
    await signInContext.post("/api/v1/auth/callback/credentials", {
        form: { username, password, csrfToken: csrf.csrfToken, callbackUrl: URL_localhost },
        maxRedirects: 0,
    });
    const { cookies } = await signInContext.storageState();
    const session = cookies.find((cookie: any) => cookie.name === "next-auth.session-token");
    await signInContext.dispose();
    if (!session) {
        throw new Error(`Signing in as ${username} returned no next-auth session token`);
    }
    return playwright.request.newContext({
        baseURL: URL_localhost,
        extraHTTPHeaders: { Authorization: `Bearer ${session.value}` },
    });
}

// Registers the secondary account, or resolves its id when it already exists.
export async function resolveUserId(
    client: SkyrampClient,
    username: string = MEMBER_USERNAME,
    password: string = MEMBER_PASSWORD,
    name: string = MEMBER_NAME,
) {
    const usersPostResponse = await createUser(client, username, password, name);
    if (usersPostResponse.statusCode === 201) {
        return { userId: Number(getResponseValue(usersPostResponse, "response.id")), usersPostResponse };
    }
    const usersResponse = await getUsersList(client);
    const existing = JSON.parse(usersResponse.responseBody).response
        .find((user: any) => user.username === username);
    if (!existing) {
        throw new Error(`No account named ${username} exists and registering one was refused`);
    }
    return { userId: Number(existing.id), usersPostResponse };
}

export async function signIn(page: Page, username: string, password: string) {
    await page.getByTestId("username-input").fill(username);
    await page.getByTestId("password-input").fill(password);
    await page.getByTestId("submit-login-button").click();
}

export async function inviteMemberByEmail(page: Page, email: string) {
    await page.getByRole("textbox", { name: "Invite by email…" }).fill(email);
    const responsePromise = page.waitForResponse("**/api/v1/collections/**/members**");
    await page.getByRole("button", { name: "Invite" }).click();
    return responsePromise;
}

export async function openTransferOwnershipModal(page: Page) {
    await page.getByRole("button", { name: "Transfer Ownership" }).click();
    await page.getByRole("combobox").waitFor({ state: "visible" });
}
